actions.script:
const out = ec.service.sync().name('ironstone.projects.ResourceServices.get#Planner').parameters({fromDate: fromDate || null, weeks: Number(weeks) || 12,
    rootWorkEffortId: rootWorkEffortId || null, roleTypeId: roleTypeId || null, skillTypeEnumId: skillTypeEnumId || null,
    teamPartyId: teamPartyId || null}).call() || {}
if (ec.message.hasError() || !out.planner) { ec.message.clearErrors(); ec.web.sendJsonResponse({notAvailable: true}); return }
ec.web.sendJsonResponse({planner: out.planner})

const out = ec.service.sync().name('ironstone.projects.ResourceServices.save#Allocation').parameters({workEffortAllocationId: workEffortAllocationId || null,
    workEffortId: allocWorkEffortId || null, partyId: partyId || null, roleTypeId: allocRoleTypeId ?? null, skillTypeEnumId: allocSkillTypeEnumId ?? null,
    fromDate: allocFromDate || null, thruDate: allocThruDate || null, amount: amount ?? null, unit: unit || 'h', comments: comments ?? null,
    request: request || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {workEffortAllocationId: out.workEffortAllocationId, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.projects.ResourceServices.move#Allocation').parameters({workEffortAllocationId: workEffortAllocationId || '',
    shiftDays: shiftDays ? Number(shiftDays) : null, fromDate: allocFromDate || null, thruDate: allocThruDate || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {moved: true, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.projects.ResourceServices.decide#Allocation').parameters({workEffortAllocationId: workEffortAllocationId || '',
    action: action || '', reason: reason || null, partyId: partyId || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {decided: true, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.projects.ResourceServices.get#StaffCandidates').parameters({workEffortAllocationId: workEffortAllocationId || ''}).call() || {}
if (ec.message.hasError()) { ec.message.clearErrors(); ec.web.sendJsonResponse({notAvailable: true}); return }
ec.web.sendJsonResponse({allocation: out.allocation, candidateList: out.candidateList || [], canStaff: !!out.canStaff, ratesShown: !!out.ratesShown})

const out = ec.service.sync().name('ironstone.projects.ResourceServices.search#AllocationPeople').parameters({term: term || null, fromDate: allocFromDate || null,
    thruDate: allocThruDate || null, amount: amount || null, unit: unit || null}).call() || {}
ec.message.clearErrors()
ec.web.sendJsonResponse(out.optionList || [])
